def calc(expr: str) -> int | str:
    n = len(expr)
    i = 0

    def skip_ws() -> None:
        nonlocal i
        while i < n and expr[i] == " ":
            i += 1

    def parse_expr() -> int:
        nonlocal i
        val = parse_term()
        while True:
            skip_ws()
            if i < n and expr[i] in "+-":
                op = expr[i]
                i += 1
                rhs = parse_term()
                val = val + rhs if op == "+" else val - rhs
            else:
                return val

    def parse_term() -> int:
        nonlocal i
        val = parse_unary_power()
        while True:
            skip_ws()
            if i < n and expr[i] in "*/%":
                op = expr[i]
                i += 1
                rhs = parse_unary_power()
                if op == "*":
                    val *= rhs
                else:
                    if rhs == 0:
                        raise ArithmeticError
                    q = abs(val) // abs(rhs)
                    if (val < 0) ^ (rhs < 0):
                        q = -q
                    val = q if op == "/" else val - rhs * q
            else:
                return val

    def parse_unary_power() -> int:
        nonlocal i
        stack: list[tuple[bool, int]] = []
        while True:
            neg = False
            while True:
                skip_ws()
                if i < n and expr[i] == "-":
                    neg = not neg
                    i += 1
                else:
                    break
            val = parse_atom()
            skip_ws()
            if i < n and expr[i] == "^":
                stack.append((neg, val))
                i += 1
            else:
                res = -val if neg else val
                break
        while stack:
            neg, base = stack.pop()
            if res < 0:
                raise ArithmeticError
            res = pow(base, res)
            if neg:
                res = -res
        return res

    def parse_atom() -> int:
        nonlocal i
        skip_ws()
        if expr[i] == "(":
            i += 1
            val = parse_expr()
            skip_ws()
            i += 1
            return val
        start = i
        while i < n and "0" <= expr[i] <= "9":
            i += 1
        return int(expr[start:i])

    try:
        return parse_expr()
    except ArithmeticError:
        return "error"
